local module = {}
local OriginPositions = {}

function module.In(obj: GuiObject, tweenInfo: TweenInfo?, callback)
    if obj:IsA("GuiObject") then
        if not OriginPositions[obj] then
            OriginPositions[obj] = obj.Position
        end
        obj.Position = OriginPositions[obj]
        obj.Visible = true
        callback()
        return {
            Cancel = function()
            end
        }
    end
end

function module.Out(obj: GuiObject, tweenInfo: TweenInfo?, callback)
    if obj:IsA("GuiObject") then
        if not OriginPositions[obj] then
            OriginPositions[obj] = obj.Position
        end
        obj.Position = OriginPositions[obj]
        obj.Visible = false
        callback()
        return {
            Cancel = function()
            end
        }
    end
end

return module